package dev.kelmagic.client;
import net.minecraft.client.model.HumanoidModel;
import net.minecraft.client.model.geom.*;
import net.minecraft.client.model.geom.builders.*;
import net.minecraft.world.entity.*;
/** Four original, slot-specific humanoid meshes; vanilla joint names keep walk/sneak poses. */
public final class ArtifactArmorModel extends HumanoidModel<LivingEntity> {
    private final String set;
    public ArtifactArmorModel(String set,EquipmentSlot slot){super(mesh(set,slot));this.set=set;}
    public void animate(LivingEntity e){if(body.hasChild("front_skirt")){float step=(float)Math.sin(e.walkAnimation.position()*.6662)*Math.min(.6f,e.walkAnimation.speed());body.getChild("front_skirt").xRot=-.1f-Math.abs(step)*.3f;body.getChild("back_skirt").xRot=.12f+Math.abs(step)*.28f;}}
    private static void box(PartDefinition p,String name,int u,int v,float x,float y,float z,float w,float h,float d,float dilation){p.addOrReplaceChild(name,CubeListBuilder.create().texOffs(u,v).addBox(x,y,z,w,h,d,new CubeDeformation(dilation)),PartPose.ZERO);}
    private static ModelPart mesh(String set,EquipmentSlot slot){boolean robe=set.equals("deep_source")||set.equals("grove_keeper"),grove=set.equals("grove_keeper"),neg=set.equals("strict_negation");var mesh=new MeshDefinition();var r=mesh.getRoot();var head=r.addOrReplaceChild("head",CubeListBuilder.create(),PartPose.ZERO);r.addOrReplaceChild("hat",CubeListBuilder.create(),PartPose.ZERO);var body=r.addOrReplaceChild("body",CubeListBuilder.create(),PartPose.ZERO);var ra=r.addOrReplaceChild("right_arm",CubeListBuilder.create(),PartPose.offset(-5,2,0));var la=r.addOrReplaceChild("left_arm",CubeListBuilder.create(),PartPose.offset(5,2,0));var rl=r.addOrReplaceChild("right_leg",CubeListBuilder.create(),PartPose.offset(-1.9f,12,0));var ll=r.addOrReplaceChild("left_leg",CubeListBuilder.create(),PartPose.offset(1.9f,12,0));
        if(slot==EquipmentSlot.HEAD){if(robe){box(head,"hood_top",0,0,-4.5f,-9,-4.5f,9,2,9,0);box(head,"hood_left",40,0,-4.5f,-7,-4.5f,1,7,9,0);box(head,"hood_right",40,0,3.5f,-7,-4.5f,1,7,9,0);box(head,"hood_back",0,40,-3.5f,-7,3.5f,7,7,1,0);box(head,"brow_gem",64,48,-.7f,-8.2f,-4.9f,1.4f,1.8f,.6f,0);if(grove){head.addOrReplaceChild("leaf_crown",CubeListBuilder.create().texOffs(80,48).addBox(-1,-4,0,2,5,1),PartPose.offsetAndRotation(-4,-7,0,0,0,-.45f));head.addOrReplaceChild("leaf_crown_other",CubeListBuilder.create().texOffs(80,48).addBox(-1,-4,0,2,5,1),PartPose.offsetAndRotation(4,-7,0,0,0,.45f));}else box(head,"nape_fold",96,48,-3,-9,3.5f,6,5,2,0);}else{box(head,"helm",0,0,-4,-8,-4,8,8,8,.55f);box(head,"brow",64,0,-4.8f,-7,-5,9.6f,1.5f,1,0);box(head,"visor",80,20,-3.8f,-4.8f,-4.9f,7.6f,1.6f,.7f,0);if(neg){box(head,"crest",96,0,-.7f,-11,-3,1.4f,4,6,0);box(head,"cheek_left",64,32,-4.8f,-4,-4,1.4f,4,3,0);box(head,"cheek_right",64,32,3.4f,-4,-4,1.4f,4,3,0);}else box(head,"crown_band",64,16,-4.9f,-8.5f,-4.9f,9.8f,2,9.8f,0);}}
        if(slot==EquipmentSlot.CHEST){box(body,"torso",16,16,-4,0,-2,8,12,4,.6f);box(ra,"sleeve",40,16,-3,-2,-2,4,robe?10:11,4,.5f);box(la,"sleeve",40,16,-1,-2,-2,4,robe?10:11,4,.5f);box(body,"girdle",64,64,-4.7f,8.8f,-2.8f,9.4f,2,5.6f,0);box(body,"heart_gem",64,48,-.8f,3,-3.1f,1.6f,2.5f,.7f,0);
            if(robe){box(body,"mantle",64,0,-5,-.2f,-3,10,3,6,0);body.addOrReplaceChild("front_skirt",CubeListBuilder.create().texOffs(64,80).addBox(-4.3f,0,-.3f,8.6f,9,.6f),PartPose.offsetAndRotation(0,11,-2.7f,-.1f,0,0));body.addOrReplaceChild("back_skirt",CubeListBuilder.create().texOffs(88,80).addBox(-4.3f,0,-.3f,8.6f,10,.6f),PartPose.offsetAndRotation(0,11,2.7f,.12f,0,0));if(grove){box(ra,"leaf_guard",96,16,-3.8f,-2.8f,-2.6f,5.6f,3.2f,5.2f,0);box(la,"branch_guard",96,32,-1.6f,-2.5f,-2.4f,4.7f,2.5f,4.8f,0);}else{box(ra,"cuff",96,16,-3.6f,6,-2.6f,5.2f,3,5.2f,0);box(la,"cuff",96,16,-1.6f,6,-2.6f,5.2f,3,5.2f,0);}}
            else{box(ra,"pauldron",64,0,-4,-3,-3,6,4,6,0);box(la,"pauldron",64,0,-2,-3,-3,6,4,6,0);box(body,"breast_seal",96,64,-3.5f,2,-3,7,6,1,0);if(neg){box(ra,"silence_blade",96,0,-3.7f,-4,-1,1,5,2,0);box(la,"silence_blade",96,0,2.7f,-4,-1,1,5,2,0);}else{box(ra,"arm_band",96,16,-3.7f,5,-2.7f,5.4f,3,5.4f,0);box(la,"arm_band",96,16,-1.7f,5,-2.7f,5.4f,3,5.4f,0);}}
        }
        if(slot==EquipmentSlot.LEGS){box(body,"waist",16,16,-4,9,-2,8,3,4,.35f);box(rl,"leg",0,16,-2,0,-2,4,11,4,.35f);box(ll,"leg",0,16,-2,0,-2,4,11,4,.35f);if(!robe){box(rl,"knee",64,32,-2.5f,4,-3,5,3,1.2f,0);box(ll,"knee",64,32,-2.5f,4,-3,5,3,1.2f,0);}}
        if(slot==EquipmentSlot.FEET){box(rl,"boot",0,16,-2,8,-2,4,4,4,.6f);box(ll,"boot",0,16,-2,8,-2,4,4,4,.6f);box(rl,"toe",64,32,-2.5f,10,-3.4f,5,2,1.8f,0);box(ll,"toe",64,32,-2.5f,10,-3.4f,5,2,1.8f,0);if(robe){box(rl,"binding",64,64,-2.7f,8,-2.7f,5.4f,1,5.4f,0);box(ll,"binding",64,64,-2.7f,8,-2.7f,5.4f,1,5.4f,0);}}
        return LayerDefinition.create(mesh,128,128).bakeRoot();
    }
}
